// Dynamic coverage of the exact recorded shortest walk for each directed
// terminal edge. In particular, reversing an edge does not assume the same
// visibility on a tied shortest path.
struct DirectedPathCoverage {
    using Leg=std::pair<int,int>;
    const Solver& map;
    BipartiteEdgeCoverCounter cells;
    std::unordered_map<uint64_t,std::vector<int>> edge_segments;
    int h;
    static vector<pair<int,int>> incidences(const Solver& map) {
        vector<pair<int,int>> result;
        for(int i=0;i<int(map.roads.size());++i)
            result.emplace_back(map.horizontal_segment[i],map.vertical_segment[i]);
        return result;
    }
    explicit DirectedPathCoverage(const Solver& map_)
        :map(map_),cells(int(map.horizontal_members.size()),int(map.vertical_members.size()),incidences(map)),
         h(int(map.horizontal_members.size())) {}
    const vector<int>& segments(Leg leg) {
        auto [a,b]=leg;
        uint64_t key=(uint64_t(a)<<32)|uint32_t(b);
        auto [it,created]=edge_segments.try_emplace(key);
        if(created) {
            auto& vals=it->second;
            int source=map.terminals[a],x=map.terminals[b];
            for(;;) {
                vals.push_back(map.horizontal_segment[x]);
                vals.push_back(h+map.vertical_segment[x]);
                if(x==source)break;
                x=map.shortest_path_parent[a][x];
                if(x<0)throw std::logic_error("invalid shortest-path entry");
            }
            std::sort(vals.begin(),vals.end());
            vals.erase(std::unique(vals.begin(),vals.end()),vals.end());
        }
        return it->second;
    }
    void change(Leg leg,int delta) {
        for(int x:segments(leg))cells.add(x>=h,x>=h?x-h:x,delta);
    }
    int length(Leg leg) const { return map.distance_between_terminals[leg.first][leg.second]; }
};

static vector<int> path_aware_polish(const Solver& map, vector<int> order,
          chrono::steady_clock::time_point deadline,bool extended,int& accepts) {
    using Leg=DirectedPathCoverage::Leg;
    DirectedPathCoverage coverage(map);
    auto at=[&](int i){return order[i%int(order.size())];};
    for(int i=0;i<int(order.size());++i)coverage.change({at(i),at(i+1)},1);
    if(!coverage.cells.all_covered())return order;
    auto consider=[&](const vector<Leg>& remove,const vector<Leg>& append) {
        int delta=0;
        for(auto p:remove)delta-=coverage.length(p);
        for(auto p:append)delta+=coverage.length(p);
        if(delta>=0)return false;
        for(auto p:remove)coverage.change(p,-1);
        for(auto p:append)coverage.change(p,1);
        if(!coverage.cells.all_covered()){
            for(auto p:append)coverage.change(p,-1);
            for(auto p:remove)coverage.change(p,1);
            return false;
        }
        ++accepts;
        return true;
    };
    mt19937 rng(629911);
    // The default leaves a strictly decreasing integer cost as a simple
    // invariant; this is a short finishing optimization, not an anneal.
    for(int iter=0;iter<12000&&order.size()>2;++iter){
        if(chrono::steady_clock::now()>=deadline)break;
        int z=int(order.size());
        int i=1+int(rng()%(z-1)),k=extended?int(rng()%3):0;
        if(k<=1) {
            int last=i+(k==1&&i+1<z);
            if(last-i+1>=z-1)continue;
            vector<Leg> gone;
            for(int t=i-1;t<=last;++t)gone.push_back({at(t),at(t+1)});
            if(consider(gone,{{at(i-1),at(last+1)}}))
                order.erase(order.begin()+i,order.begin()+last+1);
        } else {
            int j=int(rng()%z);
            if(j==i||j==i-1)continue;
            int a=at(i-1),x=at(i),b=at(i+1),u=at(j),v=at(j+1);
            if(consider({{a,x},{x,b},{u,v}},{{a,b},{u,x},{x,v}})){
                order.erase(order.begin()+i);
                order.insert(order.begin()+j+1-(j>i),x);
            }
        }
    }
    return order;
}
#endif  // AHC_BUNDLE_7911FE7660760C38059A0F3AE5EF5CFED624EBBB919255880A48CDC0637F6C45
// end: problems/ahc005/path-aware.hpp
#endif

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  const auto started = chrono::steady_clock::now();
  auto elapsed = [&] { return chrono::duration<double,milli>(chrono::steady_clock::now()-started).count(); };
  Solver solver;
  solver.read_input();
  string answer = solver.solve();  // 既存の合法な短時間解も保険として保存する。
  auto travel_cost = [&](const string& route) {
    int r=solver.start_row, c=solver.start_column, cost=0;
    for (char ch : route) {
      if (ch == 'U') --r;
      if (ch == 'D') ++r;
      if (ch == 'L') --c;
      if (ch == 'R') ++c;
      cost += solver.grid[r][c]-'0';
    }
    return cost;
  };
  const int legacy_cost = travel_cost(answer);
  PatrolProblem problem(solver);
  auto initial = problem.initial_state();
  const int initial_score = -initial.cost;
  const double remaining = 2600.0-elapsed();
  vector<int> order;
  if (remaining > 0) {
    TimeBasedAnnealingRunner<PatrolProblem> runner(
        problem, std::move(initial), initial_score, remaining, 30.0, 1.0, 5, 256);
    runner.run();
    for (auto visit : runner.best_state().order) order.push_back(visit.point);
    cerr << "iterations=" << runner.iterations() << '\n';
  } else {
    for (auto visit : initial.order) order.push_back(visit.point);
  }
  // 通過途中の視界も利用し、期限内だけ不要な代表点を削る。
  solver.remove_unneeded_waypoints(order, started+chrono::milliseconds(2820));
  string candidate = solver.make_answer(order);
#ifdef AHC005_PATH_AWARE_DIAGNOSTIC
  if(solver.answer_is_valid(candidate) && !candidate.empty()) {
    const int common=travel_cost(candidate);
    int entered_control=0,entered_aware=0;
    auto now=chrono::steady_clock::now();
    auto a=path_aware_polish(solver,order,min(now+chrono::milliseconds(66),started+chrono::milliseconds(2825)),false,entered_control);
    now=chrono::steady_clock::now();
    auto b=path_aware_polish(solver,order,min(now+chrono::milliseconds(66),started+chrono::milliseconds(2895)),true,entered_aware);
    string ca=solver.make_answer(a),cb=solver.make_answer(b);
    bool valid_a=solver.answer_is_valid(ca)&&!ca.empty(),valid_b=solver.answer_is_valid(cb)&&!cb.empty();
    if(!valid_a||!valid_b)throw logic_error("path-aware coverage invariant");
    cerr<<"path_common="<<common<<" path_control="<<travel_cost(ca)<<" path_extended="<<travel_cost(cb)
        <<" path_control_moves="<<entered_control<<" path_extended_moves="<<entered_aware<<' ';
    if(travel_cost(cb)<common)candidate=std::move(cb);
  }
#endif
  if (solver.answer_is_valid(candidate) && travel_cost(candidate) < legacy_cost)
    answer = std::move(candidate);
#ifdef AHC005_SPLICE
  const int before=travel_cost(answer);
  const auto cutoff=started+chrono::milliseconds(2910);
  if(chrono::steady_clock::now()<cutoff) {
    string changed=splice_realized_walk(solver,answer,cutoff);
    if(travel_cost(changed)<before)answer=std::move(changed);
  }
  cerr<<"before_splice="<<before<<' ';
#endif
  cerr << "travel=" << travel_cost(answer) << " legacy=" << legacy_cost << '\n';
  cout << answer << '\n';
}
